<?php
require_once dirname(__DIR__).'/includes/functions.php';require_role('student');$uid=(int)user()['id'];$stmt=$con->prepare('SELECT a.*,j.title,j.company,j.location FROM job_applications a JOIN job_opportunities j ON j.id=a.job_id WHERE a.user_id=? ORDER BY a.applied_at DESC');$stmt->bind_param('i',$uid);$stmt->execute();$apps=$stmt->get_result();$pageTitle='My applications';require dirname(__DIR__).'/includes/header.php';?>
<div class="container py-5 job-page"><div class="d-flex justify-content-between align-items-start gap-3 mb-4"><div><h1>My applications</h1><p class="text-muted">Track your status and read counselor feedback.</p></div><a class="btn btn-primary" href="<?=url('jobs/browse.php')?>"><i class="bi bi-search"></i> Find jobs</a></div><div class="row g-3"><?php foreach($apps as $a):?><div class="col-12"><article class="card p-4"><div class="d-flex flex-column flex-md-row justify-content-between gap-2"><div><h2 class="h5 mb-1"><?=e($a['title'])?></h2><div><?=e($a['company'])?> · <?=e($a['location']?:'Location flexible')?></div></div><span class="status-pill status-active align-self-start"><?=e(ucwords(str_replace('_',' ',$a['status'])))?></span></div><div class="small text-muted mt-2">Applied <?=e($a['applied_at'])?></div><?php if($a['reviewer_feedback']):?><div class="application-feedback mt-3"><strong><i class="bi bi-chat-left-text"></i> Counselor feedback</strong><p class="mb-0 mt-2"><?=nl2br(e($a['reviewer_feedback']))?></p></div><?php else:?><div class="small text-muted mt-3">No reviewer feedback yet.</div><?php endif?></article></div><?php endforeach?></div><?php if(!$apps->num_rows):?><div class="card p-5 text-center"><h2 class="h5">No applications yet</h2><p class="text-muted">Browse open opportunities and apply with your saved resume.</p></div><?php endif?></div><?php require dirname(__DIR__).'/includes/footer.php';?>
